function renderRanks(){
  var pans = paneNodes();
  Array.prototype.forEach.call(pans[step].querySelectorAll(".disc-list"), function(ul){
    var lis = ul.querySelectorAll(".item");
    Array.prototype.forEach.call(lis, function(li, idx){
      var rk = li.querySelector(".rank");
      if (rk) rk.textContent = (idx + 1);
    });
  });
}

