// ============================
// drag-and-drop (HTML5 DnD — desktop + Chrome Android)
// ============================
function makeSortable(ul){
  var lis = ul.querySelectorAll(".item");
  var dragging = null;

  Array.prototype.forEach.call(lis, function(li){
    li.setAttribute("draggable", "true");
    var handle = li.querySelector(".dots");
    if (handle) handle.setAttribute("draggable", "false");
  });

  function itemAt(y){
    for (var i = 0; i < lis.length; i++){
      var rect = lis[i].getBoundingClientRect();
      if (y < rect.top + rect.height / 2) return lis[i];
    }
    return null;
  }

  ul.addEventListener("dragstart", function(e){
    dragging = e.target.closest(".item");
    if (!dragging) return;
    dragging.classList.add("dragging");
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", "x");
  });

  ul.addEventListener("dragover", function(e){
    e.preventDefault();
    if (!dragging || dragging !== e.target.closest(".item")){
      return;
    }
    var before = itemAt(e.clientY) !== dragging;
    if (before){
      ul.insertBefore(dragging, e.target.closest(".item"));
    } else {
      ul.appendChild(dragging);
    }
  });

  ul.addEventListener("dragend", function(e){
    if (dragging) dragging.classList.remove("dragging");
    dragging = null;
    renderRanks();
  });
}

