// drag-and-drop (HTML5, desktop + touch fallback)
// ============================
function makeSortable(ul){
  var lis = ul.querySelectorAll(".item");
  var dragging = null;

  function pointer(e){ return e.touches ? e.touches[0] : e; }

  function onDragStart(e){
    dragging = this;
    this.classList.add("dragging");
    if (e.type === "touchstart"){
      e.preventDefault();
      document.addEventListener("touchmove", onDragMove, {passive: false});
      document.addEventListener("touchend", onDragEnd);
    } else {
      e.dataTransfer.effectAllowed = "move";
    }
  }
  function onDragMove(e){
    if (!dragging) return;
    if (e.type === "touchmove") e.preventDefault();
    var y = pointer(e).clientY;
    var after = false;
    var curX = pointer(e).clientX;
    Array.prototype.forEach.call(ul.querySelectorAll(".item"), function(li){
      if (li === dragging || li.contains(dragging)) return;
      var box = li.getBoundingClientRect();
      var afterThis = (e.type === "touchmove")
        ? (y < box.top + box.height / 2)
        : false;
      li.classList.toggle("over", afterThis);
    });
  }
  function onDragEnd(e){
    if (!dragging) return;
    var y = pointer(e).clientY;
    var insertBefore = null;
    Array.prototype.forEach.call(ul.querySelectorAll(".item"), function(li){
      if (li === dragging) return;
      li.classList.remove("over");
      var box = li.getBoundingClientRect();
      var yy = (e.type === "touchend") ? e.changedTouches[0].clientY : y;
      if (yy < box.top + box.height / 2){
        insertBefore = li;
      }
    });
    // reorder
    if (insertBefore){
      ul.insertBefore(dragging, insertBefore);
    } else {
      ul.appendChild(dragging);
    }
    dragging.classList.remove("dragging");
    dragging = null;
    document.removeEventListener("touchmove", onDragMove);
    document.removeEventListener("touchend", onDragEnd);
    renderRanks();
  }

  Array.prototype.forEach.call(lis, function(li){
    if (MOBILE){
      li.addEventListener("touchstart", onDragStart, {passive: false});
    } else {
      li.setAttribute("draggable", "true");
      li.addEventListener("dragstart", onDragStart);
      li.addEventListener("dragend", onDragEnd);
    }
  });
}

